-- KHEM — Cookie Policy: visitor statistics are cookieless and not consent-gated
-- (prompts/umami-count-every-visitor.md).
--
-- Umami counts every visit regardless of the cookie banner, because it sets no
-- cookies and stores nothing on the visitor's device. The published policy
-- still listed Analytics as a cookie category, so it is corrected here, EN and
-- AR alike:
--   · "How We Use Them": two categories (Essential, Preferences), not three;
--   · new section "Visitor Statistics, Without Cookies" naming Umami;
--   · "Managing Cookies": no longer mentions analytics cookies;
--   · "updatedAt" → 2026-11-21.
--
-- ## Guarded: it never overwrites an editor's work
--
-- The policy is a CMS document. This replaces `sections` / `sections_ar` only
-- when BOTH still equal the text seeded in 0003/0008 exactly (jsonb equality,
-- so key order is irrelevant). If either was edited in /admin since, nothing
-- changes and a NOTICE says so — make the same edits in the admin legal editor
-- instead (src/docs/umami-analytics.md, "First-time setup"). Re-running after
-- success is a no-op that says "already applied".
--
-- A migration does not trigger on-demand revalidation, and /cookie-policy is
-- held for up to seven days. Apply this BEFORE the deploy that ships the code
-- change: the rebuild re-prerenders the page from the new row.
--
-- Data only, no schema change. Applied directly (single transaction), like
-- 0073–0079 — never via `npm run db:migrate` while 0072b is held back
-- (supabase/README.md).

begin;

do $migration$
declare
  seeded_en jsonb := $seed_en$[{"id": "what-a-cookie-is", "title": "What A Cookie Is", "blocks": [{"kind": "text", "text": "A cookie is a small text file a website stores on your device. It lets the site recognise your browser the next time you arrive — which is how a shopping bag survives a page refresh, and how you stay signed in between visits."}]}, {"id": "how-we-use-them", "title": "How We Use Them", "blocks": [{"kind": "text", "text": "Three categories, and no others:"}, {"kind": "table", "table": {"head": ["Category", "What it does"], "rows": [["Essential", "Keeps you signed in, keeps your bag intact, shows prices in your currency, and secures checkout. These cannot be switched off — without them the shop does not work."], ["Preferences", "Remembers your region and the fragrances you have recently viewed."], ["Analytics", "Anonymous, aggregated data on which pages are read and where visitors get stuck. It tells us what to fix; it does not tell us who you are."]]}}]}, {"id": "the-currency-cookie", "title": "The Currency Cookie", "blocks": [{"kind": "text", "text": "One cookie is worth describing on its own, because it is the only one set from where you are. When you arrive, we read the country your connection resolves to and store a single three-letter currency code — EGP, USD, EUR, GBP, AED, or SAR — under the name khem.currency.v1, so the prices you see are in money you recognise."}, {"kind": "text", "text": "Your IP address is not stored, your country is not stored, and nothing about your location is logged or shared. Only the currency code is kept, only for a year, and only on your own device. Change the currency in the footer at any time and your choice replaces the detected one for good."}, {"kind": "note", "text": "We treat this as an essential cookie: without it a price cannot be shown, and it carries no identifier, so it cannot be used to recognise you here or anywhere else. Our prices are set in Egyptian Pounds; every other currency is converted at an indicative rate, and your order is charged in Egyptian Pounds."}]}, {"id": "what-we-do-not-do", "title": "What We Do Not Do", "blocks": [{"kind": "note", "text": "We run no advertising cookies. We work with no ad networks, we do not follow you onto other websites, and we neither sell nor share your browsing data with third-party advertisers."}, {"kind": "text", "text": "This is worth stating plainly, because most policies of this kind quietly say the opposite. If that ever changes, this page changes first, and we will ask before it does."}]}, {"id": "managing-cookies", "title": "Managing Cookies", "blocks": [{"kind": "text", "text": "Every major browser lets you see the cookies a site has set, delete them, and block new ones — usually under Privacy or Settings. Your browser's help pages describe the exact steps."}, {"kind": "text", "text": "Blocking preference and analytics cookies costs you nothing but a little convenience. Blocking essential cookies will break the shopping bag and prevent checkout from completing."}]}, {"id": "how-long-they-last", "title": "How Long They Last", "blocks": [{"kind": "text", "text": "Session cookies disappear the moment you close your browser. The rest expire no later than twelve months after your last visit, and are deleted automatically when they do."}]}, {"id": "more-information", "title": "More Information", "blocks": [{"href": "/privacy-policy", "kind": "link", "text": "Some cookies process limited personal data such as an IP address. How we handle that, and the rights you have over it, are set out in our", "label": "Privacy Policy"}, {"kind": "text", "text": "Anything still unclear can go to info@khemperfumes.com."}]}]$seed_en$::jsonb;
