begin
  update public."LegalDocument"
     set sections    = next_en,
         sections_ar = next_ar,
         "updatedAt" = date '2026-11-21'
   where slug = 'cookie-policy'
     and sections = seeded_en
     and sections_ar is not distinct from seeded_ar;

  if found then
    raise notice 'cookie-policy: updated to the cookieless-analytics wording (EN + AR).';
  elsif exists (
    select 1 from public."LegalDocument"
     where slug = 'cookie-policy' and sections = next_en and sections_ar = next_ar
  ) then
    raise notice 'cookie-policy: already applied — nothing to do.';
  else
    raise notice 'cookie-policy: edited since seeding (or missing) — NOT changed. Make the same edits in /admin → legal pages.';
  end if;
end
$migration$;

